use std::env;
use std::sync::Arc;
use tokio::net::TcpListener;
use tokio_tungstenite::accept_async;
use futures_util::{StreamExt, SinkExt};
use jsonwebtoken::{decode, encode, DecodingKey, EncodingKey, Header, Validation, Algorithm};
use serde::{Deserialize, Serialize};
use tokio_tungstenite::tungstenite::Message;

#[derive(Debug, Serialize, Deserialize, Clone)]
struct Claims {
    sub: String,
    role: String,
    exp: usize,
}

struct ServerConfig {
    hmac_secret: String,
    rsa_public_key: Vec<u8>,
    allowed_algorithms: Vec<Algorithm>,
}

impl ServerConfig {
    fn from_env() -> Self {
        let hmac_secret = env::var("JWT_HMAC_SECRET")
            .unwrap_or_else(|_| "default-dev-secret".to_string());
        let rsa_public_key = env::var("JWT_RSA_PUBLIC_KEY")
            .map(|k| k.into_bytes())
            .unwrap_or_else(|_| Vec::new());
        let algo_config = env::var("JWT_ALGORITHMS")
            .unwrap_or_else(|_| "RS256,HS256".to_string());
        let allowed_algorithms = parse_algorithms(&algo_config);
        ServerConfig { hmac_secret, rsa_public_key, allowed_algorithms }
    }
}

fn parse_algorithms(config: &str) -> Vec<Algorithm> {
    config.split(',').filter_map(|s| match s.trim() {
        "RS256" => Some(Algorithm::RS256),
        "RS384" => Some(Algorithm::RS384),
        "RS512" => Some(Algorithm::RS512),
        "HS256" => Some(Algorithm::HS256),
        "HS384" => Some(Algorithm::HS384),
        "HS512" => Some(Algorithm::HS512),
        _ => None,
    }).collect()
}

fn select_decoding_key(header: &jsonwebtoken::Header, config: &ServerConfig) -> Option<DecodingKey> {
    match header.alg {
        Algorithm::RS256 | Algorithm::RS384 | Algorithm::RS512 => {
            if config.rsa_public_key.is_empty() {
                None
            } else {
                DecodingKey::from_rsa_pem(&config.rsa_public_key).ok()
            }
        }
        Algorithm::HS256 | Algorithm::HS384 | Algorithm::HS512 => {
            Some(DecodingKey::from_secret(config.hmac_secret.as_bytes()))
        }
        _ => None,
    }
}

fn validate_token(token: &str, config: &ServerConfig) -> Result<Claims, String> {
    let header = jsonwebtoken::decode_header(token)
        .map_err(|e| format!("Invalid header: {}", e))?;

    // Check if the algorithm in the token header is in our allowed list
    if !config.allowed_algorithms.contains(&header.alg) {
        return Err(format!("Algorithm {:?} not allowed", header.alg));
    }

    let decoding_key = select_decoding_key(&header, config)
        .ok_or_else(|| "No suitable key for algorithm".to_string())?;

    let mut validation = Validation::new(header.alg);
    validation.validate_exp = true;
    validation.algorithms = config.allowed_algorithms.clone();

    decode::<Claims>(token, &decoding_key, &validation)
        .map(|data| data.claims)
        .map_err(|e| format!("Token validation failed: {}", e))
}

async fn handle_connection(
    stream: tokio::net::TcpStream,
    config: Arc<ServerConfig>,
) {
    let ws_stream = match accept_async(stream).await {
        Ok(ws) => ws,
        Err(_) => return,
    };

    let (mut write, mut read) = ws_stream.split();

    while let Some(Ok(msg)) = read.next().await {
        if let Message::Text(text) = msg {
            let response = if text.starts_with("AUTH:") {
                let token = &text[5..];
                match validate_token(token, &config) {
                    Ok(claims) => {
                        if claims.role == "admin" {
                            format!("ADMIN_ACCESS_GRANTED:{}", claims.sub)
                        } else {
                            format!("USER_ACCESS:{}", claims.sub)
                        }
                    }
                    Err(e) => format!("AUTH_FAILED:{}", e),
                }
            } else {
                "ERROR:Send AUTH:<token>".to_string()
            };
            if write.send(Message::Text(response)).await.is_err() {
                break;
            }
        }
    }
}

#[tokio::main]
async fn main() {
    let config = Arc::new(ServerConfig::from_env());
    let addr = env::var("LISTEN_ADDR").unwrap_or_else(|_| "127.0.0.1:9443".to_string());
    let listener = TcpListener::bind(&addr).await.expect("Failed to bind");
    println!("WebSocket server listening on {}", addr);
    println!("Allowed algorithms: {:?}", config.allowed_algorithms);

    while let Ok((stream, _)) = listener.accept().await {
        let cfg = config.clone();
        tokio::spawn(handle_connection(stream, cfg));
    }
}
